targets.expr:
sum by (service_name) (
  rate(traces_span_metrics_calls_total{
    zos_sysplex=~"$sysplex|^$",
    zos_sysplex_name=~"$sysplex|^$",
    mainframe_lpar_name=~"$lpar",
    service_name=~"$service", span_name=~".*(${subsystem:pipe}).*"
  }[$__rate_interval])
)

sum by (service_name) (
  rate(traces_span_metrics_calls_total{
    zos_sysplex=~"$sysplex|^$",
    zos_sysplex_name=~"$sysplex|^$",
    mainframe_lpar_name=~"$lpar",
    service_name=~"$service", span_name=~".*(${subsystem:pipe}).*"
  }[$__rate_interval] offset 1w)
)

100 * sum by (service_name) (
  rate(traces_span_metrics_calls_total{
    error_type!="",
    zos_sysplex=~"$sysplex|^$",
    zos_sysplex_name=~"$sysplex|^$",
    mainframe_lpar_name=~"$lpar",
    service_name=~"$service"
  }[$__rate_interval])
)
/
sum by (service_name) (
  rate(traces_span_metrics_calls_total{
    zos_sysplex=~"$sysplex|^$",
    zos_sysplex_name=~"$sysplex|^$",
    mainframe_lpar_name=~"$lpar",
    service_name=~"$service"
  }[$__rate_interval])
)
